"""Publish sanitized native evidence and source-mapped visibility rules."""
import argparse,json,subprocess
from pathlib import Path
D=Path(__file__).resolve().parent
parser=argparse.ArgumentParser()
parser.add_argument('--journal',type=Path,default=Path('/tmp/portal-device-walkthrough.json'))
args=parser.parse_args()
C=json.loads((D/'coverage.json').read_text())
document=json.loads(args.journal.read_text())
native=document['records'] if isinstance(document,dict) else document
