public=[]
for r in native:
 q=dict(r)
 if q.get('screen','').startswith('System intent verification:'):
  q['reportedActivity']=q.pop('component',q.get('reportedActivity'))
  q['note']='Intent resolved; am start reports an existing task root in some cases. Entry-page labels are recorded separately; no private values published.'
 # No screenshot, credential, network or personal-media payload is published.
 q['labels']=[x for x in q.get('labels',[]) if not ('/storage/' in x)] if 'labels' in q else None
 if q.get('labels') is None:q.pop('labels',None)
 public.append(q)
(D/'device-walkthrough.json').write_text(json.dumps({'device':'Connected Portal+','method':'USB UI interaction; sanitized labels only','records':public},indent=2)+'\n')
rows=[]
for c in C['registry']:
 condition=c['visibility'];native_rule=condition
 if c['derived']:native_rule='Derived status field; retained in native schema, not an editable setting'
 if c['domain']=='screensaver' and not c['derived'] and not c['hidden'] and c['key']!='enabled':native_rule='Photo-frame enabled AND ('+condition+')'
 if c['domain']=='sunrise':native_rule='Always present on native Sunrise editor; registry predicate applies to remote'
 if c['key'] in ('pauseAudioOnSleep','closeAppOnSleep'):native_rule+='; standalone Sleep editor always presents this row'
 rows.append({**c,'nativeRule':native_rule})
audit={'revision':'03','sourceCommit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=D.parent.parent,text=True).strip(),'families':[dict(zip(['title','screen','parent','behavior','source','evidence'],g)) for g in groups],'registry':rows,'nativeRecords':len(public),'nativeScreens':sorted(set(r.get('screen','Chime') for r in public)),'limitations':['Existing Home Assistant discovery was verified on the device. Unconfigured Immich, SMB and WebDAV server replies use source-mapped fixtures; no connection was replaced to manufacture a hardware test.','Intentional destructive paths (install, uninstall, admin removal, credential replacement, physical HA actuation) were mapped without executing them.','Installed version and source commit alone do not prove identical APK bytes. Native visual parity requires the approved implementation and screenshot comparison.']}
if any(r.get('screen')=='Tools: Speed test verified' and not r.get('metricsVisible') for r in public):
 audit['limitations'].append('The installed Speed test tile did not expose its metric pane during USB checks. Its source-defined metric/progress/retry UI is mapped in the mock; native opening must be verified during implementation.')
(D/'state-audit.json').write_text(json.dumps(audit,indent=2)+'\n')
